"""Build static, searchable original GATE ME revision books and offline editions."""
from pathlib import Path
from html import escape as e
import json
from gate_books_content import BOOKS

ROOT = Path(__file__).absolute().parent
PAGES = ROOT / 'engineering-careers'
ASSETS = ROOT / 'assets' / 'gate-books'
ASSETS.mkdir(parents=True, exist_ok=True)
BASE = 'https://chamanprakashkanth.github.io/Mechanical-Engineering-Market-Position-Dashboard/'
SYLLABUS = 'https://gate2027.iitm.ac.in/static/doc/GATE2027_Syllabus/ME_GATE2027_Syllabus.pdf'
HUB = 'gate-mechanical-books.html'
CSS = '''
:root{color-scheme:dark;--bg:#0b151c;--card:#12232e;--ink:#f3f6f8;--muted:#b9cbd7;--accent:#a8ecd2;--line:#354b59}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:radial-gradient(ellipse at 90% 0,#153e40,transparent 48%),var(--bg);color:var(--ink);font:17px/1.75 system-ui,sans-serif}header,main,footer{max-width:1150px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;border-bottom:1px solid var(--line)}nav,.actions,.tags{display:flex;gap:18px;flex-wrap:wrap}a{color:var(--accent);text-underline-offset:4px}.brand{font-size:23px;font-weight:800;text-decoration:none}.eyebrow{letter-spacing:.14em;text-transform:uppercase;color:var(--accent);font-size:12px;font-weight:800}h1{font-size:clamp(36px,5vw,62px);line-height:1.12;letter-spacing:-.04em;max-width:930px}h2{font-size:29px;line-height:1.3}h3{font-size:21px;line-height:1.4}.intro{font-size:20px;max-width:850px;color:var(--muted)}p,li{color:var(--muted)}strong{color:var(--ink)}.panel,.book{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:26px;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.grid .book{margin:0}.number{font-size:14px;color:var(--accent)}.tags span{font-size:13px;border:1px solid var(--line);padding:5px 12px;border-radius:99px}.actions{margin:22px 0}.button,button{border:1px solid var(--accent);background:var(--accent);color:#102620;padding:12px 18px;border-radius:10px;font:inherit;font-weight:700;text-decoration:none;cursor:pointer}.secondary{background:transparent;color:var(--accent)}input{display:block;width:100%;background:#09141c;color:var(--ink);border:1px solid #6b899c;border-radius:10px;padding:15px;font:inherit;margin-top:10px}label{font-weight:700}.result{border-bottom:1px solid var(--line);padding:16px 0}.result p{margin:6px 0;font-size:15px}mark{background:#f5e7a9;color:#18232b}.formula{font-family:ui-monospace,monospace;white-space:pre-wrap;border-left:4px solid var(--accent);padding:16px;background:#09141c;overflow-wrap:anywhere}.example{background:#18333c;border-radius:12px;padding:20px}.chapter{padding-top:24px;border-top:1px solid var(--line);margin-top:35px}.chapter:target{outline:2px solid var(--accent);outline-offset:12px}details{margin:12px 0;border:1px solid var(--line);border-radius:10px;padding:14px}summary{cursor:pointer;font-weight:700;color:var(--accent)}.toc a{display:block;padding:8px 0}footer{font-size:14px;border-top:1px solid var(--line)}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #f5d885;outline-offset:4px}[hidden]{display:none!important}@media(max-width:700px){.grid{grid-template-columns:1fr}header,main,footer{padding:18px}.panel,.book{padding:20px}.intro{font-size:18px}}@media print{:root{color-scheme:light;--ink:#111;--muted:#222;--card:#fff;--line:#aaa;--accent:#174737}body{background:white;font-size:11pt}header,.no-print,.search,footer,.actions{display:none!important}main{max-width:none;padding:0}.panel,.book,.example{background:white;border-color:#aaa}.formula{background:#f4f4f4;color:#111}.chapter{break-before:page;outline:none}details{break-inside:avoid}h1{font-size:30pt}h2{font-size:21pt}a{color:#174737}p,li{color:#222}}
'''
SCRIPT = '''
const input=document.getElementById('book-search'),results=document.getElementById('search-results'),status=document.getElementById('search-status');
const index=JSON.parse(document.getElementById('search-index').textContent);
input.addEventListener('input',()=>{const q=input.value.trim().toLocaleLowerCase(),terms=q.split(/\\s+/).filter(Boolean);results.replaceChildren();if(!q){status.textContent='Search all chapter explanations, formulas, examples and practice answers.';return;}const matches=index.filter(item=>terms.every(term=>item.text.toLocaleLowerCase().includes(term)));status.textContent=matches.length+' matching chapter'+(matches.length===1?'':'s');for(const item of matches){const box=document.createElement('div');box.className='result';const link=document.createElement('a');link.href=item.url;link.textContent=item.book+' → '+item.title;const p=document.createElement('p');const lower=item.text.toLocaleLowerCase();const at=lower.indexOf(terms[0]);p.textContent=(at>70?'…':'')+item.text.slice(Math.max(0,at-70),Math.max(0,at-70)+240)+'…';box.append(link,p);results.append(box);}});
document.querySelectorAll('[data-print]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('details').forEach(item=>item.open=true);window.print();}));
'''

def filename(book):
    return 'gate-mechanical-' + book['slug'] + '.html'

def search(records):
    return '<section class="panel search" aria-labelledby="search-heading"><h2 id="search-heading">Search the books</h2><label for="book-search">Topic, formula or question</label><input id="book-search" type="search" placeholder="Try torsion, thermal resistance, EOQ or eigenvalues" autocomplete="off"><p id="search-status" role="status" aria-live="polite">Search all chapter explanations, formulas, examples and practice answers.</p><div id="search-results"></div></section><script type="application/json" id="search-index">' + json.dumps(records, ensure_ascii=False).replace('<','\\u003c') + '</script>'

def document(name, desc, path, body, schema, records):
    url = BASE+'engineering-careers/'+path
    crumbs = {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'MechIntel','item':BASE},{'@type':'ListItem','position':2,'name':'GATE Mechanical books','item':BASE+'engineering-careers/'+HUB}]}
    if path != HUB:
        crumbs['itemListElement'].append({'@type':'ListItem','position':3,'name':name,'item':url})
    head = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(name)+' | MechIntel</title><meta name="description" content="'+e(desc, quote=True)+'"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="'+url+'"><meta property="og:type" content="website"><meta property="og:title" content="'+e(name,quote=True)+'"><meta property="og:description" content="'+e(desc,quote=True)+'"><meta property="og:url" content="'+url+'"><meta property="og:image" content="'+BASE+'assets/mechintel-social-cover.png"><meta name="twitter:card" content="summary_large_image"><style>'+CSS+'</style>'
    for data in [schema,crumbs]:
        head += '<script type="application/ld+json">'+json.dumps(data,ensure_ascii=False).replace('<','\\u003c')+'</script>'
    return head+'</head><body><header><a class="brand" href="../">MechIntel.ai</a><nav aria-label="Main navigation"><a href="'+HUB+'">GATE Books</a><a href="cad-library.html">CAD Library</a><a href="../#resume-builder">Resume Builder</a></nav></header><main>'+body+'</main><footer>Original MechIntel learning material · First edition, 15 October 2026 · AI-assisted authoring · Independent resource, not affiliated with the GATE organizers. Check the <a href="'+SYLLABUS+'">official GATE 2027 ME syllabus</a> for full scope. Released under <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>.</footer><script>'+SCRIPT+'</script></body></html>'

records=[]
for book in BOOKS:
    for c in book['chapters']:
        text=' '.join([book['title'],c['title'],c['concept'],c['formula'],c['example'],c['solution'],c['mistakes']] + [q+' '+a for q,a in c['practice']])
        records.append(dict(book=book['title'],title=c['title'],text=text,url=filename(book)+'#'+c['slug']))

for n,book in enumerate(BOOKS,1):
    name='GATE Mechanical '+book['title']+' — Free Revision Book'
    desc='Free original GATE ME '+book['title'].lower()+' revision book: four chapters, worked examples, practice questions with solutions and offline downloads.'
    md=['# '+name,'','Original MechIntel first edition · 15 October 2026 · CC BY 4.0.','AI-assisted educational material. Original questions, not official previous-year questions.','Official syllabus: '+SYLLABUS,'','## Coverage and further study',book['subtitle']+'. '+book['gaps'],'']
    body='<p class="eyebrow">GATE Mechanical Engineering · Volume '+str(n)+' · Original revision book</p><h1>'+e(book['title'])+'</h1><p class="intro">'+e(book['subtitle'])+'. Four foundation chapters with explanations, worked examples and eight original practice questions.</p><div class="tags"><span>Free to read</span><span>Offline edition</span><span>Worked solutions</span></div><div class="actions no-print"><button type="button" data-print>Print / Save as PDF</button><a class="button secondary" download href="../assets/gate-books/'+book['slug']+'.md">Download text book (.md)</a><a class="button secondary" download href="'+filename(book)+'">Download offline HTML</a></div><section class="panel"><h2>How to use this book</h2><p>Read each concept, solve the example before looking at its solution, then attempt the practice problems. Record the assumption or unit conversion behind each error. All practice questions are newly authored; none are presented as official GATE questions.</p><p><strong>Coverage:</strong> This is a focused revision book, not full syllabus coverage. '+e(book['gaps'])+'</p></section>'+search(records)+'<nav class="panel toc" aria-label="Book contents"><h2>Contents</h2>'
    body+=''.join('<a href="#'+c['slug']+'">'+str(i)+'. '+e(c['title'])+'</a>' for i,c in enumerate(book['chapters'],1))+'</nav>'
    for i,c in enumerate(book['chapters'],1):
        body+='<article class="chapter" id="'+c['slug']+'"><p class="eyebrow">Chapter '+str(i)+'</p><h2>'+e(c['title'])+'</h2><p>'+e(c['concept'])+'</p><h3>Key relations and assumptions</h3><p class="formula">'+e(c['formula'])+'</p><section class="example"><h3>Worked example</h3><p>'+e(c['example'])+'</p><h4>Solution</h4><p>'+e(c['solution'])+'</p></section><h3>Common mistakes</h3><p>'+e(c['mistakes'])+'</p><h3>Original practice questions</h3>'
        md += ['## '+str(i)+'. '+c['title'],'',c['concept'],'','### Key relations',c['formula'],'','### Worked example',c['example'],'','Solution: '+c['solution'],'','### Common mistakes',c['mistakes'],'','### Practice']
        for j,(q,a) in enumerate(c['practice'],1):
            body+='<p><strong>'+str(i)+'.'+str(j)+'.</strong> '+e(q)+'</p><details><summary>Show answer and reasoning</summary><p>'+e(a)+'</p></details>'
            md += [str(j)+'. '+q,'Answer: '+a,'']
        body+='<p class="no-print"><a href="#search-heading">Search another topic ↑</a></p></article>'
    body+='<section class="panel no-print"><h2>Continue studying</h2><p><a href="'+HUB+'">Browse all four GATE Mechanical books →</a></p><p>Use the <a href="'+SYLLABUS+'">official ME syllabus</a> to plan the remaining topics. Supplement these original exercises with official previous-year papers and timed practice.</p></section>'
    url=BASE+'engineering-careers/'+filename(book)
    schema={'@context':'https://schema.org','@type':'Book','name':name,'url':url,'description':desc,'author':{'@type':'Organization','name':'MechIntel'},'inLanguage':'en','bookFormat':'https://schema.org/EBook','isAccessibleForFree':True,'datePublished':'2026-10-15','license':'https://creativecommons.org/licenses/by/4.0/','hasPart':[{'@type':'Chapter','name':c['title'],'url':url+'#'+c['slug']} for c in book['chapters']]}
    (PAGES/filename(book)).write_text(document(name,desc,filename(book),body,schema,records),encoding='utf-8')
    (ASSETS/(book['slug']+'.md')).write_text('\n'.join(md),encoding='utf-8')

body='<p class="eyebrow">New · GATE ME study library</p><h1>Free GATE Mechanical Engineering books</h1><p class="intro">Original revision books for GATE aspirants. Search concepts and formulas, follow 16 worked examples, and practise 32 questions with explained answers.</p><div class="tags"><span>4 original books</span><span>16 chapters</span><span>No signup</span><span>Works without AI tokens or GPU</span></div>'+search(records)+'<section aria-labelledby="books"><h2 id="books">Choose your revision book</h2><div class="grid">'
for n,book in enumerate(BOOKS,1):
    body+='<article class="book"><p class="eyebrow">Volume '+str(n)+' · 4 chapters</p><h3><a href="'+filename(book)+'">'+e(book['title'])+'</a></h3><p>'+e(book['subtitle'])+'.</p><ul>'+''.join('<li><a href="'+filename(book)+'#'+c['slug']+'">'+e(c['title'])+'</a></li>' for c in book['chapters'])+'</ul><div class="actions"><a class="button" href="'+filename(book)+'">Read book</a><a download href="../assets/gate-books/'+book['slug']+'.md">Download text</a></div></article>'
body+='</div></section><section class="panel"><h2>A practical revision routine</h2><ol><li>Pick one chapter and read its assumptions before using a formula.</li><li>Attempt the worked example on paper. Compare units and intermediate steps.</li><li>Answer both practice questions before revealing their solutions.</li><li>Keep an error log and revisit the chapter after two days and one week.</li><li>Track uncovered topics against the official syllabus and add official previous-year problems.</li></ol><p>The <a href="'+SYLLABUS+'">official GATE 2027 Mechanical Engineering syllabus</a> defines the exam scope. These four first-edition books cover selected foundations within its main subject groups; they do not replace the complete syllabus or General Aptitude preparation.</p></section><section class="panel"><h2>Frequently asked questions</h2><h3>Are these GATE Mechanical books free?</h3><p>Yes. Read all chapters online, download the text or offline HTML edition, or use Print / Save as PDF. The print button expands practice answers so they are included.</p><h3>Can I search formulas and solved questions?</h3><p>Yes. Search scans the complete chapter explanations, formulas, worked examples and practice answers across all four books. Every chapter is also readable without JavaScript.</p><h3>Are these official GATE books or previous-year questions?</h3><p>No. These are original, AI-assisted MechIntel revision books and newly authored practice questions. The official syllabus is linked for scope verification. This edition covers selected topics and has not undergone independent subject-expert review.</p><h3>Can I reuse the material?</h3><p>Yes, under CC BY 4.0: credit MechIntel, link the license and indicate changes.</p></section>'
schema={'@context':'https://schema.org','@type':'CollectionPage','name':'Free GATE Mechanical Engineering Books','url':BASE+'engineering-careers/'+HUB,'description':'Four original revision books with 16 worked examples and 32 practice questions.','mainEntity':{'@type':'ItemList','numberOfItems':len(BOOKS),'itemListElement':[{'@type':'ListItem','position':i,'url':BASE+'engineering-careers/'+filename(b),'name':b['title']} for i,b in enumerate(BOOKS,1)]}}
(PAGES/HUB).write_text(document('Free GATE Mechanical Engineering Books & Solved Examples','Search four original GATE ME revision books: mathematics, mechanics, thermal sciences and manufacturing. Read 16 chapters and 32 practice solutions, or download offline.',HUB,body,schema,records),encoding='utf-8')
print('Generated 4 books, 16 chapters, 16 worked examples, 32 practice questions and a searchable library.')
